#include "TradeMissionRuntime.hpp"
#include <algorithm>
#include <cmath>
namespace elysium::economy {bool TradeMissionRuntime::add(TradeMission m,std::string&w){if(!m.id||!m.origin||!m.destination){w="invalid trade mission";return false;}m.routeRisk=std::clamp(std::isfinite(m.routeRisk)?m.routeRisk:0.0,0.0,1.0);return rows_.emplace(m.id,std::move(m)).second;}bool TradeMissionRuntime::advance(StableId id,TradeStage s,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown mission";return false;}if(std::uint8_t(s)<std::uint8_t(i->second.stage)){w="stage regression";return false;}i->second.stage=s;return true;}bool TradeMissionRuntime::settle(StableId id,std::uint64_t r,std::string&w){auto i=rows_.find(id);if(i==rows_.end()||i->second.stage!=TradeStage::Settle){w="not settlement stage";return false;}if(i->second.settlementReceipt){w="already settled";return false;}i->second.settlementReceipt=r?r:1;return true;}std::optional<TradeMission>TradeMissionRuntime::get(StableId id)const{auto i=rows_.find(id);if(i==rows_.end())return std::nullopt;return i->second;}}
